'use strict';

// MODULES //

var path = require( 'node:path' );
var fs = require( 'node:fs/promises' );
var equal = require( '@data-apis/canonical/equal' );
var sha256 = require( '@data-apis/canonical/sha256' );
var walkFiles = require( '@data-apis/files/walk-files' );
var indexKey = require( '@data-apis/record/index-key' );
var filenameTimestamp = require( '@data-apis/record/filename-timestamp' );
var parsePath = require( '@data-apis/record/parse-path' );
var serializeIndex = require( '@data-apis/record/serialize-index' );
var normalizeTimestamp = require( '@data-apis/report/normalize-timestamp' );
var validateEnvelope = require( '@data-apis/publish/validate-envelope' );


// FUNCTIONS //

/**
* Reads and strictly decodes a JSON file.
*
* @private
* @param {string} filePath - file path
* @returns {Promise<Object>} parsed value
*/
async function readJson( filePath ) {
	var bytes = await fs.readFile( filePath );

	return JSON.parse( new TextDecoder( 'utf-8', { 'fatal': true } ).decode( bytes ) );
}

/**
* Asserts that an object has exactly the listed fields.
*
* @private
* @param {Object} value - object
* @param {Array<string>} fields - field names
* @param {string} name - object name
*/
function requireExactFields( value, fields, name ) {
	if ( !value || typeof value !== 'object' || Array.isArray( value ) || JSON.stringify( Object.keys( value ).sort() ) !== JSON.stringify( fields.slice().sort() ) ) {
		throw new Error( name + ' fields are malformed' );
	}
}

/**
* Validates the publication manifest.
*
* @private
* @param {Object} manifest - manifest
*/
function validateManifest( manifest ) {
	var seen = new Set();
	var previous = '';

	requireExactFields( manifest, ['schema', 'base_sha', 'files'], 'manifest' );
	if ( manifest.schema !== 'harvest-manifest-v1' || !/^[0-9a-f]{40}$/.test( manifest.base_sha ) || !Array.isArray( manifest.files ) ) {
		throw new Error( 'Publication manifest is malformed' );
	}
	manifest.files.forEach( function validateFile( file ) {
		requireExactFields( file, ['path', 'size', 'sha256'], 'manifest file' );
		if ( typeof file.path !== 'string' || !Number.isSafeInteger( file.size ) || file.size < 0 || !/^[0-9a-f]{64}$/.test( file.sha256 ) ) {
			throw new Error( 'Publication manifest file entry is malformed' );
		}
		if ( file.path !== 'data/index.json' && !/^data\/[a-z0-9-]+\/[a-z0-9-]+\/\d{4}_\d{2}_\d{2}T\d{2}_\d{2}_\d{2}Z__sha256_[0-9a-f]{64}\.json\.gz$/.test( file.path ) ) {
			throw new Error( 'Publication path is not whitelisted: ' + file.path );
		}
		if ( seen.has( file.path ) || ( previous && previous > file.path ) ) {
			throw new Error( 'Publication manifest paths are duplicate or unsorted' );
		}
		seen.add( file.path );
		previous = file.path;
	} );
}

/**
* Validates the machine summary against the manifest.
*
* @private
* @param {Object} summary - summary
* @param {Object} manifest - manifest
*/
function validateSummary( summary, manifest ) {
	var recordPaths;

	requireExactFields( summary, ['schema', 'base_sha', 'has_source_errors', 'new_records', 'sources', 'warnings'], 'summary' );
	if ( summary.schema !== 'harvest-summary-v1' || summary.base_sha !== manifest.base_sha || typeof summary.has_source_errors !== 'boolean' || !Array.isArray( summary.new_records ) || !Array.isArray( summary.sources ) || !Array.isArray( summary.warnings ) ) {
		throw new Error( 'Publication summary is malformed' );
	}
	if ( new Set( summary.new_records ).size !== summary.new_records.length || !equal( summary.new_records, summary.new_records.slice().sort() ) ) {
		throw new Error( 'Publication summary paths are duplicate or unsorted' );
	}
	recordPaths = manifest.files.filter( function records( file ) {
		return file.path.endsWith( '.json.gz' );
	} ).map( function paths( file ) {
		return file.path;
	} );
	if ( !equal( summary.new_records, recordPaths ) ) {
		throw new Error( 'Publication summary and manifest records differ' );
	}
}

/**
* Validates index shape, ordering, and unique identifiers.
*
* @private
* @param {Object} index - index
* @param {string} serialized - serialized index
* @param {string} name - diagnostic name
* @returns {Map} rows keyed by path
*/
function validateIndex( index, serialized, name ) {
	var paths;
	var keys;

	requireExactFields( index, ['schema', 'records'], name );
	if ( index.schema !== 'data-index-v1' || !Array.isArray( index.records ) ) {
		throw new Error( name + ' is malformed' );
	}
	if ( serialized !== serializeIndex( index.records ) ) {
		throw new Error( name + ' does not use deterministic serialization and ordering' );
	}
	paths = new Map( index.records.map( function mapRow( row ) {
		var parsed;
		var timestamp;

		if ( !row || typeof row !== 'object' || Array.isArray( row ) || typeof row.path !== 'string' ) {
			throw new Error( name + ' contains a malformed row' );
		}
		parsed = parsePath( row.path );
		timestamp = normalizeTimestamp( row.timestamp );
		if ( row.library_id !== parsed.libraryId || row.source_id !== parsed.sourceId || row.report_sha256 !== parsed.reportSha256 || timestamp !== row.timestamp || filenameTimestamp( timestamp ) !== parsed.filenameTimestamp ) {
			throw new Error( name + ' row does not agree with its path: ' + row.path );
		}
		return [row.path, row];
	} ) );
	keys = new Set( index.records.map( indexKey ) );
	if ( paths.size !== index.records.length || keys.size !== index.records.length ) {
		throw new Error( name + ' contains duplicate paths or keys' );
	}
	return paths;
}

/**
* Finds a registered library and source by immutable IDs.
*
* @private
* @param {Object} registry - registry
* @param {string} libraryId - library ID
* @param {string} sourceId - source ID
* @returns {Object} library and source
*/
function findSource( registry, libraryId, sourceId ) {
	var library;
	var source;

	if ( !registry || registry.schema !== 'registry-v1' || !Array.isArray( registry.libraries ) ) {
		throw new Error( 'Checked-in registry is malformed' );
	}
	library = registry.libraries.find( function matchLibrary( item ) {
		return item && item.id === libraryId;
	} );
	source = library && Array.isArray( library.sources ) ? library.sources.find( function matchSource( item ) {
		return item && item.id === sourceId;
	} ) : undefined;
	if ( !library || !source ) {
		throw new Error( 'Publication references an unregistered source: ' + libraryId + '/' + sourceId );
	}
	return { 'library': library, 'source': source };
}


// MAIN //

/**
* Verifies a transfer bundle using only trusted standard-library-backed modules.
*
* @param {Object} options - verification options
* @param {string} options.rootDirectory - repository root
* @param {string} options.outputDirectory - transfer directory
* @param {string} [options.expectedBaseSha] - expected source revision
* @returns {Promise<Object>} verified publication inputs
*/
async function verifyTransfer( options ) {
	var manifest = await readJson( path.join( options.outputDirectory, 'manifest.json' ) );
	var summary = await readJson( path.join( options.outputDirectory, 'summary.json' ) );
	var actualFiles = await walkFiles( options.outputDirectory );
	var expectedFiles;
	var files = [];
	var recordFiles;
	var registry;
	var existingText;
	var existingIndex;
	var existingRows;
	var outputFile;
	var outputText;
	var outputIndex;
	var outputRows;
	var newRows = new Map();
	var records = [];
	var sourceProjectIds = new Map();
	var priorProjectId;
	var components;
	var sourceKey;
	var validated;
	var relative;
	var lookup;
	var bytes;
	var item;
	var file;

	validateManifest( manifest );
	validateSummary( summary, manifest );
	if ( options.expectedBaseSha && manifest.base_sha !== options.expectedBaseSha ) {
		throw new Error( 'Manifest base revision differs from the expected revision' );
	}
	expectedFiles = ['manifest.json', 'summary.json'].concat( manifest.files.map( function filePath( file ) {
		return file.path;
	} ) ).sort();
	if ( !equal( actualFiles, expectedFiles ) ) {
		throw new Error( 'Publication directory contains files outside the manifest' );
	}
	for ( item of manifest.files ) {
		bytes = await fs.readFile( path.join( options.outputDirectory, ...item.path.split( '/' ) ) );

		if ( bytes.length !== item.size || sha256( bytes ) !== item.sha256 ) {
			throw new Error( 'Publication file hash mismatch: ' + item.path );
		}
		files.push( { 'path': item.path, 'bytes': bytes } );
	}
	recordFiles = files.filter( function recordsOnly( file ) {
		return file.path.endsWith( '.json.gz' );
	} );
	if ( recordFiles.length === 0 ) {
		if ( files.length !== 0 ) {
			throw new Error( 'No-change publication must not contain data files' );
		}
		return { 'manifest': manifest, 'summary': summary, 'files': files, 'records': records };
	}
	if ( files.filter( function indexOnly( file ) { return file.path === 'data/index.json'; } ).length !== 1 ) {
		throw new Error( 'Changed publication must contain exactly one data/index.json' );
	}
	registry = await readJson( path.join( options.rootDirectory, 'registry/data.json' ) );
	existingText = await fs.readFile( path.join( options.rootDirectory, 'data/index.json' ), 'utf8' );
	existingIndex = JSON.parse( existingText );
	existingRows = validateIndex( existingIndex, existingText, 'Checked-in index' );
	outputFile = files.find( function findIndex( file ) { return file.path === 'data/index.json'; } );
	outputText = new TextDecoder( 'utf-8', { 'fatal': true } ).decode( outputFile.bytes );
	outputIndex = JSON.parse( outputText );
	outputRows = validateIndex( outputIndex, outputText, 'Publication index' );
	if ( outputIndex.records.length !== existingIndex.records.length + recordFiles.length ) {
		throw new Error( 'Publication index does not have exact historical and new coverage' );
	}
	existingRows.forEach( function preserve( row, recordPath ) {
		var sourceKey;
		var priorProjectId;

		if ( !equal( outputRows.get( recordPath ), row ) ) {
			throw new Error( 'Publication changed a historical index row: ' + recordPath );
		}
		if ( row.origin && row.origin.type === 'ci_artifact' ) {
			sourceKey = row.library_id + '/' + row.source_id;
			priorProjectId = sourceProjectIds.get( sourceKey );
			if ( priorProjectId && priorProjectId !== row.origin.project.id ) {
				throw new Error( 'Checked-in source contains multiple immutable project IDs: ' + sourceKey );
			}
			sourceProjectIds.set( sourceKey, row.origin.project.id );
		}
	} );
	for ( file of recordFiles ) {
		relative = file.path.slice( 'data/'.length );
		components = relative.split( '/' );
		lookup = findSource( registry, components[ 0 ], components[ 1 ] );

		if ( existingRows.has( relative ) ) {
			throw new Error( 'Publication would overwrite an existing record: ' + relative );
		}
		await fs.access( path.join( options.rootDirectory, ...file.path.split( '/' ) ) ).then( function exists() {
			throw new Error( 'Publication would overwrite an existing record: ' + relative );
		} ).catch( function absent( error ) {
			if ( error.code !== 'ENOENT' ) {
				throw error;
			}
		} );
		validated = validateEnvelope( file.bytes, relative, lookup.library, lookup.source );
		if ( validated.row.origin.type === 'ci_artifact' ) {
			sourceKey = validated.row.library_id + '/' + validated.row.source_id;
			priorProjectId = sourceProjectIds.get( sourceKey );
			if ( priorProjectId && priorProjectId !== validated.row.origin.project.id ) {
				throw new Error( 'Publication changed the source immutable project ID: ' + sourceKey );
			}
			sourceProjectIds.set( sourceKey, validated.row.origin.project.id );
		}
		if ( !equal( outputRows.get( relative ), validated.row ) ) {
			throw new Error( 'Publication index does not agree with new record: ' + relative );
		}
		newRows.set( relative, validated.row );
		records.push( { 'path': relative, 'reportSha256': validated.row.report_sha256 } );
	}
	if ( newRows.size !== recordFiles.length || outputRows.size !== existingRows.size + newRows.size || Array.from( outputRows.keys() ).some( function unexpected( recordPath ) {
		return !existingRows.has( recordPath ) && !newRows.has( recordPath );
	} ) ) {
		throw new Error( 'Publication index coverage is not exact' );
	}
	return {
		'manifest': manifest,
		'summary': summary,
		'files': files,
		'records': records,
		'index': outputIndex
	};
}


// EXPORTS //

module.exports = verifyTransfer;
